-- C2+C3 — banque metcon v4. appliquée en prod : non
-- Appliquer avant merge / OTA 1.0.55. Les anciens lecteurs gardent les définitions v3.
-- Le nouveau lecteur utilise definition.c2c3 ; les nouveaux squelettes ont durations=[] pour les anciens lecteurs.
BEGIN;

-- ── Seed : banque v4 (30 squelettes, généré par packages/wod-engine/scripts/export-bank.ts) ──
ON CONFLICT (id) DO UPDATE SET
  discipline = EXCLUDED.discipline, format = EXCLUDED.format, definition = EXCLUDED.definition,
  active = EXCLUDED.active, version = EXCLUDED.version, updated_at = now();

-- ── Seed : plafonds §5.4 (20 classes) ──
ON CONFLICT (label) DO UPDATE SET
  ids = EXCLUDED.ids, family = EXCLUDED.family, band = EXCLUDED.band, unit = EXCLUDED.unit,
  rx_total = EXCLUDED.rx_total, active = EXCLUDED.active, version = EXCLUDED.version, updated_at = now();

COMMIT;
